pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // amount must be > 1 wei so the invariant is non-trivial, and <= address(this).balance
        vm.assume(amount > 1);
        vm.assume(amount <= address(this).balance);

        // fund the test contract and deposit via fallback
        vm.deal(address(this), amount);
        (bool ok,) = address(c).call{value: amount}("");
        require(ok, "deposit failed");

        // record state before withdrawAll
        uint256 depositsBefore = c.depositsCount();
        uint256 balanceBefore = address(c).balance;

        // owner calls withdrawAll
        vm.prank(c.owner());
        c.withdrawAll();

        // After withdrawAll, contract balance should be exactly depositsCount minus 1 wei.
        // The correct version transfers the entire balance (leaving 0).
        // The mutant transfers 1 wei, leaving balanceBefore - 1.
        // So the invariant is: balanceAfter == depositsBefore - 1.
        // For the reference, depositsBefore == balanceBefore (since each fallback adds 1 deposit and 1 wei),
        // so it leaves 0: 0 == balanceBefore - 1? No, balanceBefore == depositsBefore so 0 == depositsBefore - 1
        // is equivalent to depositsBefore == 1, which is false when amount > 1.
        // Wait, depositsBefore reflects number of fallback calls, each adding 1 to depositsCount and receiving 1 wei.
        // We deposited 'amount' wei in a single fallback, so depositsBefore = previous deposits (0 from setUp) + 1.
        // So depositsBefore = 1 always. That's not useful.
        // We need multiple fallback calls to accumulate depositsCount > 1.
        // Let's deposit multiple times: we iterate to break amount into 1-wei chunks.
        // But we cannot use loops with fuzzed amount efficiently? We'll use a fixed number of deposits.
        // Actually we can split: we deposit 1 wei multiple times to reach at least 2 deposits.
        // The invariant "balanceAfter == depositsBefore - 1" still holds for reference because it withdraws all,
        // leaving 0, and depositsBefore = number of 1-wei deposits, so 0 == depositsBefore - 1 => depositsBefore == 1.
        // That again forces depositsBefore to be 1.
        //
        // The core property: withdrawAll should transfer the entire contract balance, which equals the sum of all received wei.
        // Each fallback call increments depositsCount and receives wei.
        // So contract balance before withdrawAll = sum of all received wei.
        // After correct withdrawAll, balance = 0.
        // After mutant, balance = previousBalance - 1.
        //
        // To have a universal invariant that doesn't require knowing the exact amounts, we can assert:
        // "After withdrawAll, the contract's balance is strictly less than the balance before, and the change is at least 1."
        // But the mutant also changes by 1, so it passes.
        //
        // Better: "After withdrawAll, the contract's balance is exactly 0" – that is the rule reference satisfies for ALL inputs,
        // and mutant breaks when any prior deposit > 1 wei exists.
        //
        // So we need to create a scenario with at least one deposit > 1 wei, using fallback.
        // The fallback receives the entire msg.value and increments depositsCount by 1.
        // So if we send amount > 1 via fallback, depositsCount = 1, contract balance = amount.
        // After withdrawAll (correct): balance = 0.
        // After mutant: balance = amount - 1.
        // Thus the invariant "balance == 0 after withdrawAll" holds for reference, fails for mutant when amount > 1.
        // We can fuzz 'amount' directly as msg.value to fallback.

        // To keep domain wide, we just need amount > 1 wei.
        // Additionally, we need the test contract to have the funds, so we vm.deal accordingly.
        // No adversarial party needed.

        uint256 contractBalanceAfter = address(c).balance;
        assertTrue(contractBalanceAfter == 0);
    }
}

