pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 sendAmount) public {
        // Restrict amount to a reasonable range that the contract can hold.
        // sendAmount is the amount sent via sendMoney in the second step; it must be <= amount.
        amount = bound(amount, 1, 100 ether);
        sendAmount = bound(sendAmount, 1, amount);

        // Fund the contract with 'amount' ether directly (owner is the contract deployer in setUp,
        // but C has no payable constructor; we force-send with vm.deal)
        vm.deal(address(c), amount);

        // Deploy an adversarial helper that can accept ETH (does not revert).
        // This ensures that sendMoney will succeed if the contract actually has the funds.
        Receiver receiver = new Receiver();

        // The owner withdraws the entire balance.
        vm.prank(c.owner());
        c.withdraw(amount);

        // After the withdraw, attempt to send ETH to the receiver using sendMoney.
        // In the reference, withdraw actually transferred the ETH, so the contract balance is 0,
        // and sendMoney with a positive sendAmount will revert.
        // In the buggy version, withdraw did nothing, so the contract still has 'amount' ether,
        // and sendMoney succeeds.
        bool sendSucceeded;
        vm.prank(c.owner());
        try c.sendMoney(address(receiver), sendAmount) {
            sendSucceeded = true;
        } catch {
            sendSucceeded = false;
        }

        // The invariant: after the owner withdraws the full balance, the contract should be unable
        // to send any ETH via sendMoney (because it has no ETH). The buggy version breaks this
        // by leaving the funds untouched, allowing the send to succeed.
        assertTrue(!sendSucceeded);
    }
}

contract Receiver {
    // Accept ETH without reverting.
    fallback() external payable {}
}

